import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DxgWTcNC.js";const u=JSON.parse('{"title":"Patching, Writing Back, and Re-Flashing","description":"","frontmatter":{},"headers":[],"relativePath":"part4/22-patching.md","filePath":"part4/22-patching.md","lastUpdated":null}'),i={name:"part4/22-patching.md"};function o(r,e,c,p,d,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="patching-writing-back-and-re-flashing" tabindex="-1">Patching, Writing Back, and Re-Flashing <a class="header-anchor" href="#patching-writing-back-and-re-flashing" aria-label="Permalink to &quot;Patching, Writing Back, and Re-Flashing&quot;">​</a></h1><p>Sometimes the goal is not to understand the firmware but to <em>change</em> it. Bypass a license check, fix a vendor bug the manufacturer will not address, enable hidden features, instrument the binary for debugging, or write a research patch that proves a vulnerability is exploitable. This chapter covers radare2&#39;s patching workflow, the constraints that embedded targets impose, and how to write back to the underlying file safely.</p><h2 id="opening-a-binary-for-writing" tabindex="-1">Opening a binary for writing <a class="header-anchor" href="#opening-a-binary-for-writing" aria-label="Permalink to &quot;Opening a binary for writing&quot;">​</a></h2><p>By default r2 opens files read-only. Patches you make exist in r2&#39;s write cache and never touch disk. To enable real writes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -w firmware.bin</span></span></code></pre></div><p>Or in-session:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; oo+                 # reopen current file in read-write mode</span></span></code></pre></div><p>Confirm:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; i ~ rdwr</span></span></code></pre></div><p><code>io.cache = true</code> is on by default; writes go to a cache layer first and are committed when you exit (or call <code>wB</code> to write the cache back to the file). You can keep writes in the cache indefinitely and discard with <code>o-</code> if a patch turns out wrong.</p><h2 id="the-write-commands" tabindex="-1">The write commands <a class="header-anchor" href="#the-write-commands" aria-label="Permalink to &quot;The write commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Action</th></tr></thead><tbody><tr><td><code>w str</code></td><td>write a string</td></tr><tr><td><code>wz str</code></td><td>write a zero-terminated string</td></tr><tr><td><code>wx hex</code></td><td>write hex bytes (e.g., <code>wx 90909090</code>)</td></tr><tr><td><code>wa &lt;asm&gt;</code></td><td>write assembled instruction</td></tr><tr><td><code>waf file</code></td><td>write assembled instructions from a file</td></tr><tr><td><code>wo*</code></td><td>write with operations (xor, and, or, add, sub, …)</td></tr><tr><td><code>wb byte</code></td><td>write a byte pattern over a range</td></tr><tr><td><code>wf path</code></td><td>write contents of a file at the cursor</td></tr><tr><td><code>wF path</code></td><td>hex-decode a file and write the bytes</td></tr><tr><td><code>wn N val</code></td><td>write a value as N-byte int</td></tr><tr><td><code>wv val</code></td><td>write a 32-bit value</td></tr><tr><td><code>wt path N</code></td><td>write N bytes from the cursor to a file</td></tr><tr><td><code>wp script</code></td><td>write a patch (in hex format) from a file</td></tr><tr><td><code>wB val</code></td><td>bit-write (set/clear bits)</td></tr></tbody></table><p>The two you use most often: <code>wx</code> for known byte sequences and <code>wa</code> for &quot;assemble this instruction and write it&quot;.</p><h2 id="assembling-instructions" tabindex="-1">Assembling instructions <a class="header-anchor" href="#assembling-instructions" aria-label="Permalink to &quot;Assembling instructions&quot;">​</a></h2><p><code>wa</code> invokes the architecture&#39;s assembler. The syntax matches what the disassembler shows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234]&gt; wa nop                # write a NOP at current address</span></span>
<span class="line"><span>[0x08001234]&gt; wa &quot;mov r0, #0&quot;       # equivalent of &quot;return 0;&quot;</span></span>
<span class="line"><span>[0x08001234]&gt; wa &quot;bx lr&quot;            # return</span></span>
<span class="line"><span>[0x08001234]&gt; wa &quot;b 0x08001260&quot;     # unconditional branch</span></span>
<span class="line"><span>[0x08001234]&gt; wa &quot;bl 0x08005000&quot;    # call</span></span></code></pre></div><p>For multi-instruction patches, write them in sequence — <code>wa</code> advances the cursor by the size of the assembled instruction:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234]&gt; wa &quot;mov r0, #1&quot;</span></span>
<span class="line"><span>[0x08001236]&gt; wa &quot;bx lr&quot;            # cursor moved automatically</span></span></code></pre></div><p>Or use <code>waf</code> with a file:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ cat patch.s</span></span>
<span class="line"><span>mov r0, #1</span></span>
<span class="line"><span>bx lr</span></span>
<span class="line"><span>$ # in r2:</span></span>
<span class="line"><span>[0x08001234]&gt; waf patch.s</span></span></code></pre></div><h2 id="patches-in-practice" tabindex="-1">Patches in practice <a class="header-anchor" href="#patches-in-practice" aria-label="Permalink to &quot;Patches in practice&quot;">​</a></h2><p>The most common patches:</p><p><strong>Bypass a check.</strong> A function that returns <code>0</code> for &quot;valid&quot; and <code>1</code> for &quot;invalid&quot; — patch the function to always return 0:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; wa &quot;mov r0, #0&quot;</span></span>
<span class="line"><span>[0x...]&gt; wa &quot;bx lr&quot;</span></span></code></pre></div><p>Two instructions on Thumb (4 bytes). If the original function is longer, the rest is now dead code; that is fine on flash.</p><p><strong>NOP a specific instruction.</strong> Perhaps a delay or a sleep you want to skip:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234]&gt; pdf @ sym.foo</span></span>
<span class="line"><span>0x08001234  push {r7, lr}</span></span>
<span class="line"><span>0x08001236  bl sym.HAL_Delay         &lt;-- nop this</span></span>
<span class="line"><span>0x0800123a  ...</span></span>
<span class="line"><span>[0x08001234]&gt; wa nop @ 0x08001236</span></span>
<span class="line"><span>[0x08001234]&gt; wa nop @ 0x08001238    # bl is 4 bytes on Thumb-2; need 2 nops</span></span></code></pre></div><p><strong>Inline a constant change.</strong> Replace a magic constant the firmware checks against:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; /v 0xDEADBEEF              # find every 32-bit reference</span></span>
<span class="line"><span>[0x...]&gt; wv 0xCAFEBABE @ &lt;addr&gt;     # patch it</span></span></code></pre></div><p><strong>Insert a debug write.</strong> On a chip with a working UART you have identified, insert a <code>bl puts</code> call into a function entry to log when it runs. This is invasive — you have to find a hole big enough or relocate code.</p><h2 id="branching-to-extra-code" tabindex="-1">Branching to extra code <a class="header-anchor" href="#branching-to-extra-code" aria-label="Permalink to &quot;Branching to extra code&quot;">​</a></h2><p>The hard case: you want to add code that doesn&#39;t fit in the existing function&#39;s space. Approaches in order of preference:</p><p><strong>Find unused space.</strong> Many firmware images have padding regions — the linker rounds section sizes up to alignment, leaving holes. Look for stretches of <code>0xFF</code> bytes (erased flash) or <code>0x00</code>. If you find a 64-byte hole, use it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; wa &quot;&lt;your code&gt;&quot; @ 0x0800ff00     # write your code in the hole</span></span>
<span class="line"><span>[0x...]&gt; wa &quot;bl 0x0800ff00&quot; @ &lt;call site&gt;  # patch the original to call it</span></span></code></pre></div><p>Make sure your inserted code preserves all callee-saved registers and returns to the caller correctly.</p><p><strong>Repurpose a never-called function.</strong> Some firmware contains default handlers, debug code, or unused HAL functions you can overwrite. Verify it is never called (<code>axt @ sym.target</code> returns nothing) and rewrite.</p><p><strong>Steal padding inside the patched function.</strong> Sometimes the function you are patching has alignment padding (NOPs, <code>0xFF</code> bytes) between sub-blocks. You can use that padding for short additions.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Branching to extra code requires the right encoding for the architecture&#39;s branch range. ARM Thumb&#39;s <code>BL</code> reaches ±16 MiB; ARM Thumb-2 <code>B.W</code> reaches ±16 MiB; Cortex-M <code>LDR.W PC, [PC, #imm]</code> reaches arbitrary 32-bit addresses via a literal pool. Pick the right instruction for the distance you need.</p></div><h2 id="embedded-constraints-on-patching" tabindex="-1">Embedded constraints on patching <a class="header-anchor" href="#embedded-constraints-on-patching" aria-label="Permalink to &quot;Embedded constraints on patching&quot;">​</a></h2><p><strong>Flash erase granularity.</strong> You cannot rewrite a single byte of flash in place — you must erase a whole sector (1–256 KiB, chip-dependent) and rewrite it. The patched binary you flash back contains the entire sector, not just your changed bytes.</p><p><strong>Bit semantics.</strong> Flash erases to all-<code>1</code>s; programming sets bits to <code>0</code>. You can change a <code>1</code> to a <code>0</code> without erasing, but not the reverse. So a &quot;minimal&quot; patch that only flips bits in the same direction as erase-state changes is sometimes possible without a full re-flash.</p><p><strong>ECC and parity.</strong> Some chips compute ECC bits per word. A minimal in-place bit-flip patch can violate ECC. Double-check the chip&#39;s flash spec.</p><p><strong>Signature / integrity check.</strong> If the bootloader verifies the application image at boot, your patched image fails verification. You either bypass the check (patch the bootloader too) or compute the right signature (need the private key — usually impossible).</p><p><strong>Vendor-locked write protect.</strong> Some chips have read-out and write-protect bits in OTP. Once enabled they cannot be disabled. Test patches on a sacrificial unit first.</p><h2 id="writing-back-to-disk" tabindex="-1">Writing back to disk <a class="header-anchor" href="#writing-back-to-disk" aria-label="Permalink to &quot;Writing back to disk&quot;">​</a></h2><p>After patching in r2, the changes are in the write cache. To commit:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; wcl                # list cached writes</span></span>
<span class="line"><span>[0x...]&gt; wcr                # revert all cached writes</span></span>
<span class="line"><span>[0x...]&gt; wB                 # commit cache to the file</span></span>
<span class="line"><span>[0x...]&gt; q                  # quit (also commits if -w was set)</span></span></code></pre></div><p>Verify externally:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ md5sum firmware.bin firmware.bin.bak     # before and after</span></span>
<span class="line"><span>$ cmp -l firmware.bin firmware.bin.bak | head -10   # which bytes differ</span></span></code></pre></div><p>For a flashable image, the patched <code>firmware.bin</code> is what you flash:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ st-flash --reset write firmware.bin 0x08000000      # STM32 ST-Link</span></span>
<span class="line"><span>$ esptool.py write_flash 0x10000 firmware.bin         # ESP32</span></span>
<span class="line"><span>$ JLinkExe -if SWD -device STM32F407 -speed 4000 -CommanderScript flash.jlink</span></span></code></pre></div><p>For a router squashfs image you patched: rebuild the squashfs, repack into the OEM container (which usually means a CRC over the new content + a vendor-specific header), and flash via the OEM update mechanism.</p><h2 id="verifying-the-patch-on-hardware" tabindex="-1">Verifying the patch on hardware <a class="header-anchor" href="#verifying-the-patch-on-hardware" aria-label="Permalink to &quot;Verifying the patch on hardware&quot;">​</a></h2><p>Before considering a patch shipped:</p><ol><li>Diff the binary against the original to confirm only the intended bytes changed:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ cmp -l firmware.bin firmware.orig.bin</span></span></code></pre></div><ol start="2"><li>Disassemble the patched region and confirm it reads correctly:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 firmware.bin</span></span>
<span class="line"><span>[0x...]&gt; pdf @ &lt;patched function&gt;</span></span></code></pre></div><ol start="3"><li>Test on hardware. Test the modified path (does the bypass actually trigger?) and test adjacent paths (did the patch break anything else?).</li></ol><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>&quot;My patch works in the disassembler&quot; is not &quot;my patch works on hardware&quot;. The cache, the FPB (Flash Patch and Breakpoint unit on Cortex-M), the MPU, the bootloader, the integrity check, and the data cache can each silently invalidate a patched image. Always verify on real silicon for production patches.</p></div><h2 id="patches-as-scripts" tabindex="-1">Patches as scripts <a class="header-anchor" href="#patches-as-scripts" aria-label="Permalink to &quot;Patches as scripts&quot;">​</a></h2><p>For repeatable patches, save the commands as an r2 script:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span># patch_v1.r2</span></span>
<span class="line"><span>oo+                                          # writable</span></span>
<span class="line"><span>wa &quot;mov r0, #0&quot; @ 0x08001234                 # bypass check</span></span>
<span class="line"><span>wa &quot;bx lr&quot; @ 0x08001236</span></span>
<span class="line"><span>wv 0xCAFEBABE @ 0x08010000                   # change magic</span></span>
<span class="line"><span>wcr                                          # actually no, revert (test)</span></span></code></pre></div><p>Apply:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -i patch_v1.r2 firmware.bin</span></span></code></pre></div><p>Commit the script to git. Diff between firmware versions is then a script diff, and your patches travel with the project.</p><h2 id="when-patches-are-unsuitable" tabindex="-1">When patches are unsuitable <a class="header-anchor" href="#when-patches-are-unsuitable" aria-label="Permalink to &quot;When patches are unsuitable&quot;">​</a></h2><p>Some problems should be solved by replacing the whole firmware, not by patching it:</p><ul><li>Adding a feature larger than your padding budget.</li><li>Changing the linker layout (sections move around).</li><li>Targeting an actively-developed firmware that gets updated regularly (each update breaks your patches).</li></ul><p>For research, patches are often the right answer. For production, think hard before shipping a patched binary instead of a rebuilt one — the maintenance debt of patches accumulates fast.</p>`,70)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
